import { Box, Grid } from "@mui/material";
import React from "react";
import clientImg1 from "../../../../assets/images/clientsImg1.png";
import clientImg2 from "../../../../assets/images/clientsImg2.png";
import clientImg3 from "../../../../assets/images/clientsImg3.png";
import clientImg4 from "../../../../assets/images/clientsImg4.png";
import clientImg5 from "../../../../assets/images/clientsImg5.png";
import clientImg6 from "../../../../assets/images/clientsImg6.png";
import clientImg7 from "../../../../assets/images/clientsImg7.png";
import clientImg8 from "../../../../assets/images/clientsImg8.png";
import clientImg9 from "../../../../assets/images/clientsImg9.png";
import clientImg10 from "../../../../assets/images/clientsImg10.png";
import clientImg11 from "../../../../assets/images/clientsImg11.png";
import clientImg12 from "../../../../assets/images/clientsImg12.png";
import clientImg13 from "../../../../assets/images/clientsImg13.png";
import clientImg14 from "../../../../assets/images/clientsImg14.png";
import clientImg15 from "../../../../assets/images/clientsImg15.png";
import clientImg16 from "../../../../assets/images/clientsImg16.png";
import clientImg17 from "../../../../assets/images/clientsImg17.png";
import clientImg18 from "../../../../assets/images/clientsImg18.png";
import clientImg19 from "../../../../assets/images/clientsImg19.png";
import clientImg20 from "../../../../assets/images/clientsImg20.png";
import { useState } from "react";
import { useRef } from "react";
import { useEffect } from "react";

const clientImgs = [
  clientImg1,
  clientImg2,
  clientImg3,
  clientImg4,
  clientImg5,
  clientImg6,
  clientImg7,
  clientImg8,
  clientImg9,
  clientImg10,
  clientImg11,
  clientImg12,
  clientImg13,
  clientImg14,
  clientImg15,
  clientImg16,
  clientImg17,
  clientImg18,
  clientImg19,
  clientImg20,
];
const ClientsCategory = () => {
  //animation
  const [visibleIndices, setVisibleIndices] = useState([]);
  const cardsRef = useRef([]);
  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            const index = cardsRef.current.indexOf(entry.target);
            if (index !== -1 && !visibleIndices.includes(index)) {
              setVisibleIndices((prev) => [...prev, index]);
            }
          }
        });
      },
      { threshold: 0.1 }
    );

    cardsRef.current.forEach((card) => {
      if (card) {
        observer.observe(card);
      }
    });

    return () => {
      cardsRef.current.forEach((card) => {
        if (card) {
          observer.unobserve(card);
        }
      });
    };
  }, [visibleIndices]);
  return (
    <>
      <Box>
        <Grid container>
          {clientImgs.map((item, index) => (
            <Grid
              item
              xs={12}
              md={3}
              key={index}
              ref={(el) => (cardsRef.current[index] = el)}
              sx={{
                display: "flex",
                justifyContent: { xs: "center", md: "start" },
                alignItems: "end",
                opacity: visibleIndices.includes(index) ? 1 : 0,
                transform: visibleIndices.includes(index)
                  ? "translateX(0)"
                  : "translateX(-50px)",
                transition: "opacity 0.6s ease, transform 0.6s ease",
                transitionDelay: visibleIndices.includes(index)
                  ? `${index * 0.3}s` // Staggered effect by index
                  : "0s",
              }}
            >
              <img src={item} />
            </Grid>
          ))}
        </Grid>
      </Box>
    </>
  );
};

export default ClientsCategory;
