import { TabContext, TabList, TabPanel } from "@mui/lab";
import {
  Box,
  Container,
  createTheme,
  Fade,
  Grid,
  styled,
  Tab,
  Typography,
  useMediaQuery,
} from "@mui/material";
import React from "react";
import { useState, useEffect } from "react";
import ClientsCategory from "./ClientsCategory";
import "../../../../styles/animation.css";
import { axiosInstance } from "src/network/adapter";
import { ApiEndpoints } from "src/network/endpoints";
import { toastError, toastSuccess } from "src/utils/utils";
import FallbackSpinner from "src/@core/components/spinner";

const OurClients = () => {
  const CustomTab = styled(Tab)(({ theme }) => ({
    fontSize: "16px",
    [theme.breakpoints.down("sm")]: {
      fontSize: "14px",
    },
    [theme.breakpoints.up("md")]: {
      fontSize: "20px",
    },
    [theme.breakpoints.up("lg")]: {
      fontSize: "24px",
    },
    fontWeight: 600,
    lineHeight: "28px",
    textTransform: "none",
    wordBreak: "break-word",
    whiteSpace: "normal",
  }));
  const [value, setValue] = useState("");
  const theme = createTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("lg"));
  const [loading, setLoading] = useState(false);
  const [clientCategory, setClientCategory] = useState([]);

  const handleChange = (event, newValue) => {
    setValue(newValue);
  };

  const fetchClientCategory = () => {
    setLoading(true);
    axiosInstance
      .get(ApiEndpoints.CLIENT_CATEGORY.list)
      .then((response) => {
        const responseData = response.data.data;
        const activeData = responseData.filter(
          (item) => item.status === "active"
        );
        setClientCategory(activeData);
        if (responseData.length > 0) {
          setValue(responseData[0].category);
        }
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };
  useEffect(() => {
    fetchClientCategory();
  }, []);

  if (loading) return <FallbackSpinner />;
  return (
    <>
      <Box>
        <Container
          maxWidth={"xl"}
          sx={{ px: { xs: 5, sm: 10, lg: 15, xl: 20 } }}
        >
          <Grid container rowGap={{ xs: 5, md: 12 }}>
            <Grid
              item
              xs={12}
              sx={{
                display: "flex",
                flexDirection: "column",
                gap: 3,
                alignItems: "center",
              }}
            >
              <Typography
                sx={{
                  fontSize: {
                    xs: "26px",
                    sm: "36px",
                    md: "46px",
                    lg: "56px",
                  },
                  fontWeight: 500,
                  lineHeight: {
                    xs: "34px",
                    sm: "50px",
                    md: "60px",
                    lg: "70px",
                  },
                  color: "#201D28",
                  textAlign: "center",
                }}
                className="fade-in-up-whoweare"
              >
                Our Clients
              </Typography>
              <Typography
                sx={{
                  fontSize: { xs: "14px", sm: "18px" },
                  fontWeight: 500,
                  lineHeight: { xs: "26px", sm: "30px" },
                  color: "#646271",
                  textAlign: "center",
                }}
                className="fade-in-up-whoweare"
              >
                We have been providing our clients with innovative and reliable
                IT solutions for over 30 years. Our clients range from small
                businesses to large enterprises, and we work with them in a
                variety of industries.  We are committed to providing our
                clients with the best possible IT solutions. We understand that
                every client is unique, and we tailor our solutions to meet
                their specific needs. We also offer a wide range of support
                services to ensure that our clients are always up and running.
              </Typography>
            </Grid>
            <Grid item xs={12}>
              <Box sx={{ width: "100%" }}>
                <TabContext value={value} sx={{ gap: 40, display: "flex" }}>
                  <Box
                    sx={{
                      borderBottom: 1,
                      borderColor: "divider",
                    }}
                  >
                    <TabList
                      onChange={handleChange}
                      aria-label="lab API tabs example"
                      variant={isMobile ? "scrollable" : "fullWidth"}
                    >
                      {clientCategory?.map((item, index) => (
                        <CustomTab
                          label={item.category}
                          value={item.category}
                          key={index}
                        />
                      ))}
                      {/* <CustomTab label="All" value="all" />
                      <CustomTab label=" Government" value="government" />
                      <CustomTab label="Financial" value="financial" />
                      <CustomTab label="Education" value="education" />
                      <CustomTab label="Health " value="health" />
                      <CustomTab label="Media " value="media" /> */}
                    </TabList>
                  </Box>
                  {clientCategory?.map((item, index) => (
                    <Fade
                      in={value === item.category}
                      timeout={1000}
                      key={index}
                    >
                      <TabPanel value={item.category}>
                        <ClientsCategory />
                      </TabPanel>
                    </Fade>
                  ))}
                  {/* <Fade in={value === "all"} timeout={1000}>
                    <TabPanel value="all">
                      <ClientsCategory />
                    </TabPanel>
                  </Fade>
                  <Fade in={value === "government"} timeout={1000}>
                    <TabPanel value="government">Government</TabPanel>
                  </Fade>
                  <Fade in={value === "financial"} timeout={1000}>
                    <TabPanel value="financial">Financial</TabPanel>
                  </Fade>{" "}
                  <Fade in={value === "education"} timeout={1000}>
                    <TabPanel value="education">Education</TabPanel>
                  </Fade>{" "}
                  <Fade in={value === "health"} timeout={1000}>
                    <TabPanel value="health">Health</TabPanel>
                  </Fade>
                  <Fade in={value === "media"} timeout={1000}>
                    <TabPanel value="media">Media</TabPanel>
                  </Fade> */}
                </TabContext>
              </Box>
            </Grid>
          </Grid>
        </Container>
      </Box>
    </>
  );
};

export default OurClients;
